INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷八十五", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/f475a8bdeb3fc70a41e5ca601f675229b6c6bfc4/content/books/zizhi-tongjian/vol-285/year-0946/part-08/sources/library/jiuwudaishi-085-946-captive/source.txt", "note": "《旧五代史》卷八十五，段落 jiu-wudaishi-205deb4a7860-p002051；EPUB电子本，纸本及异文待核", "id": "345e6a7a-a7d9-5e72-b35f-40a8742957cb"}, {"title": "新五代史·卷二十九", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/f475a8bdeb3fc70a41e5ca601f675229b6c6bfc4/content/books/zizhi-tongjian/vol-285/year-0946/part-08/sources/library/xinwudaishi-029-jing-capture/source.txt", "note": "《新五代史》卷二十九，段落 xin-wudaishi-b08f244b9241-p001071；EPUB电子本，纸本及异文待核", "id": "d28a7cc9-8d00-5844-80e4-dfd4cee62d73"}, {"title": "资治通鉴·卷285·开运三年·十二月降帝及迎契丹", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/ecde5726bec9b8402d248a26c53a28ede8152696/content/books/zizhi-tongjian/vol-285/year-0946/part-07/sources/library/tongjian-285-946-captive-emperor/source.txt", "note": "《资治通鉴》卷285·开运三年·十二月降帝及迎契丹，段落 zizhi-tongjian-a63549944a71-p003392；已回查卷题、传主与上下文，纸本及异文待核。", "id": "e9102fd2-3993-5c29-aef7-615eec5d17d7"}, {"title": "旧五代史·卷89·桑维翰传·国亡遇害前后", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/ecde5726bec9b8402d248a26c53a28ede8152696/content/books/zizhi-tongjian/vol-285/year-0946/part-07/sources/library/jiuwudaishi-089-sang-captive/source.txt", "note": "《旧五代史》卷89·桑维翰传·国亡遇害前后，段落 jiu-wudaishi-205deb4a7860-p002135；已回查卷题、传主与上下文，纸本及异文待核。", "id": "7b9235ce-f2ce-5c4c-85f7-c6034475b192"}, {"title": "新五代史·卷9·晋本纪·开运三年", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/c7d707f140aeeb6d7f8cb666674b4e39a39263b6/content/books/zizhi-tongjian/vol-285/year-0946/part-06/sources/library/xinwudaishi-009-946/source.txt", "note": "《新五代史》卷9·晋本纪·开运三年，段落 xin-wudaishi-b08f244b9241-p000337；已回查正文卷号、传主与上下文，纸本及异文待核。", "id": "90a0bab8-962e-598e-a354-e5da6a3522fe"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "张彦泽", "aliases": ["張彥澤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，938年任镇国军节度使，在华州截击并杀死东行的凤翔叛军。生卒年本段未载。", "biography": null, "status": "draft", "id": "194d0f9a-3b17-5635-9741-dffc983ee32e"}, {"name": "桑维翰", "aliases": ["桑維翰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：桑维翰，主张自全、求援者。", "biography": null, "status": "draft", "id": "5132e50a-3ce2-55d5-8f89-fdccd6bf4f02"}, {"name": "耶律德光", "aliases": ["德光"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：耶律德光，守西楼、受号者。", "biography": null, "status": "draft", "id": "64c415ac-57fe-571c-8c6f-3ed68fb726da"}, {"name": "高行周", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化三年条所见人物：高行周。", "biography": null, "status": "draft", "id": "659c5f83-09bc-5282-8f02-4c7fa0a62729"}, {"name": "符彦卿", "aliases": ["符彥卿", "李彦卿", "李彥卿"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：符彦卿，散员都指挥使、力战者。", "biography": null, "status": "draft", "id": "c837916f-0fdf-5954-a190-597b08cd9402"}, {"name": "石延煦", "aliases": ["延煦"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "石敬瑭的孙子，石重贵养子，石延宝的兄长。946年任镇宁节度使，与赵在礼的女儿成婚；《资治通鉴》记三月庚申，《旧五代史》记四月，婚事纪月不同，分别保留。亲生父母姓名及生卒年未载。", "biography": null, "status": "draft", "id": "ed348273-f4e9-5b33-9080-aa449de66dcc"}, {"name": "石延宝", "aliases": ["石延寶", "延宝", "延寶"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "石敬瑭的孙子，石重贵养子，石延煦的弟弟。946年记石延煦婚事时，史书补叙二人为石重贵养子。亲生父母姓名与收养年月、生卒年未载。", "biography": null, "status": "draft", "id": "79b31372-7a96-5605-a27f-799f2f8a9daf"}, {"name": "石重贵", "aliases": ["石重貴"], "era": "五代十国", "birth_year": 914, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：石重贵，被叙侄子及养子身份者。", "biography": null, "status": "draft", "id": "2741e60a-9bf9-56a7-b30d-3db439caa139"}, {"name": "解里（契丹传诏者）", "aliases": ["解裏（契丹傳詔者）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》946年十二月记耶律德光派他向被拘的石重贵传话。该年八月另记一名契丹将解里被斩，两者身份无法直接统一，暂时分别建档，待异文和职务校核。生卒年未载。", "biography": null, "status": "draft", "id": "754bb5ca-fc0e-599b-9ec3-a5f1b0ce03d1"}, {"name": "李从珂", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化三年条所见人物：李从珂。", "biography": null, "status": "draft", "id": "0a45ab01-e475-5d82-9a76-16d916af5abd"}, {"name": "石敬瑭", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：石敬瑭。", "biography": null, "status": "draft", "id": "bf42d98c-7477-5be1-a767-867fe26cf617"}, {"name": "永宁公主（石敬瑭妻）", "aliases": ["永宁公主", "永寧公主"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：永宁公主（石敬瑭妻），与从荣异母的公主。", "biography": null, "status": "draft", "id": "fddc7a96-9cc5-5313-ac24-2c3189930825"}, {"name": "景延广", "aliases": ["景延廣"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：景延广，原客将、获任者。", "biography": null, "status": "draft", "id": "de8a964e-a028-50ee-8d54-2cbfda481e98"}, {"name": "乔荣", "aliases": ["喬榮", "乔莹", "喬瑩"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "原河阳牙将，随赵延寿入契丹后任回图使，在后晋经商并在大梁设邸。943年遭囚禁和没收货物，获释后把景延广的外交言辞写下并报给耶律德光。《新五代史》相同场景作喬瑩，据行动、对话和纸上记录对应同人，姓名异文与纸本待核。生卒年未载。", "biography": null, "status": "draft", "id": "2ae2b70e-45d7-5571-9504-de53081be0fd"}, {"name": "阎丕", "aliases": ["閻丕"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "景延广的从事。《新五代史》记946年末随景延广到封丘见耶律德光，一同被锁，景延广解释他只是因职随行后获释。生卒年、籍贯未载。", "biography": null, "status": "draft", "id": "945208a3-636d-56d0-a1f6-bc7dcc0539e5"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "张彦泽在夜间杀死桑维翰", "start_year": 946, "end_year": 946, "time_original": "946年十二月是夕，具体纪日各书不同", "dynasty": "五代十国", "description": "张彦泽在夜间杀死桑维翰。", "phases": [], "location_name": "大梁", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "2f26182c-accb-551b-93e3-e1f5d05104c5"}, {"title": "张彦泽用带子缠住桑维翰颈部，向耶律德光谎报为自缢", "start_year": 946, "end_year": 946, "time_original": "946年十二月桑维翰遇害后", "dynasty": "五代十国", "description": "张彦泽用带子缠住桑维翰颈部，向耶律德光谎报为自缢。", "phases": [], "location_name": "大梁", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "f583a08b-b257-5581-b07b-13babad6e5bc"}, {"title": "耶律德光称自己无意杀桑维翰，命优厚抚恤其家", "start_year": 946, "end_year": 946, "time_original": "946年十二月收到桑死报告后", "dynasty": "五代十国", "description": "耶律德光称自己无意杀桑维翰，命优厚抚恤其家。", "phases": [], "location_name": "契丹行营", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "de1ae1f7-03fc-53d7-83f8-4c7bf00566e1"}, {"title": "高行周、符彦卿到契丹牙帐投降", "start_year": 946, "end_year": 946, "time_original": "946年十二月入京后条下，具体日未载", "dynasty": "五代十国", "description": "高行周、符彦卿到契丹牙帐投降。", "phases": [], "location_name": "契丹牙帐", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "dea5afa8-ac53-5158-8cd1-2f4b398326db"}, {"title": "耶律德光因阳城战败责问符彦卿", "start_year": 946, "end_year": 946, "time_original": "946年十二月符彦卿投降后", "dy